{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Entecavir, a carbocyclic guanine nucleoside analog with the highest Morgan similarity to the query (0.6071), has an absolute oral bioavailability of 100% in humans, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Cladribine, a polar purine nucleoside analog, shows oral bioavailability of 35% in patients, demonstrating that this structural class can exceed the 20% threshold despite polar physicochemical properties.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Fludarabine, a fluorinated purine nucleoside analog, has oral bioavailability of 30–80% in patients, supporting high classification for related nucleoside analogs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Clofarabine, another halogenated purine nucleoside analog, has oral bioavailability of 57.5%, reinforcing that purine nucleoside analogs generally achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Didanosine under fasting conditions, matching the query condition, has a median F of 0.28 at 50 mg/m2, above the 20% threshold, although with lower structural similarity.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest high-similarity analogue entecavir has 100% oral bioavailability in humans, and multiple purine nucleoside analogs (cladribine, fludarabine, clofarabine) show F between 30% and 80%. Although the query is polar and passive permeability may be limited, the transferable experimental evidence from carbocyclic and related purine nucleosides supports F ≥ 20%; therefore predict high.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability data for the exact query molecule (lobucavir-like cyclobutane guanine analog).",
    "Uncertainty remains about whether the cyclobutane bis-hydroxymethyl scaffold alters transporter-mediated absorption or metabolic stability relative to entecavir.",
    "No direct assessment of intestinal permeability or active uptake for the query molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

